preset.warp:
uniform sampler2D sampler_cover;
uniform sampler2D sampler_accent;
uniform sampler2D sampler_orbit;
uniform sampler2D sampler_bla;
vec3 accent() {
  return texture(sampler_accent, vec2(0.5)).rgb;
}
// The cover's average colour at full brightness; a grey cover gives way
// to the accent, or the bands would be grey on grey.
vec3 coverTone() {
  vec3 c = textureLod(sampler_cover, vec2(0.5), 10.0).rgb;
  float top = max(max(c.r, c.g), c.b);
  float saturation = top - min(min(c.r, c.g), c.b);
  vec3 tone = top > 0.01 ? c / top * 0.85 : vec3(0.0);
  return mix(accent() * 0.7, tone, smoothstep(0.05, 0.25, saturation));
}
// The Mandelbrot set's main cardioid and big bulb are inside for certain:
// skipping their iterations is most of the cost at its overview.
bool surelyInside(vec2 c) {
  float x = c.x - 0.25;
  float q = x * x + c.y * c.y;
  if (q * (q + x) < 0.25 * c.y * c.y) return true;
  return (c.x + 1.0) * (c.x + 1.0) + c.y * c.y < 0.0625;
}
vec2 turn2(vec2 v, float a) {
  return vec2(cos(a) * v.x - sin(a) * v.y, sin(a) * v.x + cos(a) * v.y);
}
// Last frame's picture between its pixels, by Catmull-Rom rather than
// linearly: read back every frame, a linear read would soften it a little
// more each time. Nine reads, through the linear filter's own weighting.
vec3 history(vec2 uv) {
  vec2 pos = uv * texsize.xy;
  vec2 c = floor(pos - 0.5) + 0.5;
  vec2 f = pos - c;
  vec2 w0 = f * (-0.5 + f * (1.0 - 0.5 * f));
  vec2 w1 = 1.0 + f * f * (-2.5 + 1.5 * f);
  vec2 w2 = f * (0.5 + f * (2.0 - 1.5 * f));
  vec2 w3 = f * f * (-0.5 + 0.5 * f);
  vec2 w12 = w1 + w2;
  vec2 t0 = (c - 1.0) * texsize.zw;
  vec2 t3 = (c + 2.0) * texsize.zw;
  vec2 t12 = (c + w2 / w12) * texsize.zw;
  vec3 sum = texture(sampler_main, vec2(t0.x, t0.y)).rgb * w0.x * w0.y
    + texture(sampler_main, vec2(t12.x, t0.y)).rgb * w12.x * w0.y
    + texture(sampler_main, vec2(t3.x, t0.y)).rgb * w3.x * w0.y
    + texture(sampler_main, vec2(t0.x, t12.y)).rgb * w0.x * w12.y
    + texture(sampler_main, vec2(t12.x, t12.y)).rgb * w12.x * w12.y
    + texture(sampler_main, vec2(t3.x, t12.y)).rgb * w3.x * w12.y
    + texture(sampler_main, vec2(t0.x, t3.y)).rgb * w0.x * w3.y
    + texture(sampler_main, vec2(t12.x, t3.y)).rgb * w12.x * w3.y
    + texture(sampler_main, vec2(t3.x, t3.y)).rgb * w3.x * w3.y;
  return max(sum, 0.0);
}
vec2 cmul(vec2 a, vec2 b) {
  return vec2(a.x * b.x - a.y * b.y, a.x * b.y + a.y * b.x);
}
// How far the step moves d, the difference from the orbit's point Z, with
// d's digits kept: (Z + d)^n - Z^n written out, so no Z^n is taken from
// another. q25 is n; q22 set takes the conjugate first (the Tricorn).
vec2 stepAway(vec2 Z, vec2 d) {
  if (q22 > 0.5) {
    vec2 m = cmul(2.0 * Z + d, d);
    return vec2(m.x, -m.y);
  }
  if (q25 < 2.5) return cmul(2.0 * Z + d, d);
  vec2 Z2 = cmul(Z, Z);
  if (q25 < 3.5) return cmul(d, 3.0 * Z2 + cmul(3.0 * Z + d, d));
  return cmul(d, 4.0 * cmul(Z2, Z) + cmul(6.0 * Z2 + cmul(4.0 * Z + d, d), d));
}
vec4 orbitAt(int row, int n) {
  return texelFetch(sampler_orbit, ivec2(n, row), 0);
}
vec4 blaAt(int texel) {
  return texelFetch(sampler_bla, ivec2(texel & 2047, texel >> 11), 0);
}
// |v| or a little more, without squaring: d's parts sit far below where a
// float still holds their square.
float sizeOf(vec2 v) {
  return abs(v.x) + abs(v.y);
}
// The Mandelbrot set (or a relative of it, see stepAway) past where floats
// can tell pixels apart: dc is the pixel's offset from a target whose
// orbit Beacon worked out with all the digits it needs (row q21 of
// sampler_orbit), and only the pixel's difference d from that orbit is
// followed - small, but a float's exponent holds it. Where d outgrows the
// orbit's own point, or the orbit ends, it carries on from the orbit's
// start (rebasing), which keeps d from losing its digits. dzp is the
// derivative, in pixels.
//
// For the Mandelbrot set itself, sampler_bla can fold many steps into one
// while d is small (see bla.ts) - if it was built for this target and a
// view at least this wide.
bool mandelbrot(vec2 dc, float pixel, out float escaped, out float r2, out vec2 dzp) {
  int row = int(q21);
  int limit = int(q9);
  vec4 table = blaAt(0);
  bool skips = q25 < 2.5 && q22 < 0.5 && table.x == q21 && sizeOf(dc) <= table.y;
  vec2 d = vec2(0.0);
  int m = 0;
  int i = 0;
  dzp = vec2(0.0);
  for (int pass = 0; pass < 1200; pass++) {
    if (i >= limit) break;
    vec4 ref = orbitAt(row, m);
    if (ref.z < 0.5) {
      d += ref.xy;
      m = 0;
      ref = vec4(0.0);
    }
    int steps = 0;
    if (skips && m > 0) {
      float size = sizeOf(d);
      // The longest stretch that starts here and holds for this d. Each
      // level holds for no more than the one below, so the search climbs
      // and stops at the first that fails - most steps cost one look.
      int at = 0;
      for (int level = 1; level <= 10; level++) {
        int span = 1 << level;
        if (((m - 1) & (span - 1)) != 0 || i + span > limit) break;
        int here = 2048 + 2 * (2048 - (2048 >> (level - 1)) + ((m - 1) >> level));
        if (size >= blaAt(here + 1).x) break;
        at = here;
        steps = span;
      }
      if (steps > 0) {
        vec4 ab = blaAt(at);
        d = cmul(ab.xy, d) + cmul(ab.zw, dc);
        dzp = cmul(ab.xy, dzp) + ab.zw * pixel;
      }
    }
    if (steps == 0) {
      vec2 z = ref.xy + d;
      if (q22 > 0.5) {
        // Not holomorphic, so only near enough for the edge.
        vec2 turned = 2.0 * cmul(z, dzp);
        dzp = vec2(turned.x, -turned.y) + vec2(pixel, 0.0);
      } else {
        vec2 power = q25 < 2.5 ? z : q25 < 3.5 ? cmul(z, z) : cmul(cmul(z, z), z);
        dzp = q25 * cmul(power, dzp) + vec2(pixel, 0.0);
      }
      d = stepAway(ref.xy, d) + dc;
      steps = 1;
    }
    m += steps;
    i += steps;
    vec2 z = orbitAt(row, m).xy + d;
    r2 = dot(z, z);
    if (r2 > 65536.0) {
      escaped = float(i - 1);
      return true;
    }
    if (r2 < dot(d, d)) {
      d = z;
      m = 0;
    }
  }
  return false;
}
// |c + d| - |c|, without losing d's digits to c where d is far smaller.
float diffabs(float c, float d) {
  float cd = c + d;
  if (c >= 0.0) return cd >= 0.0 ? d : -(2.0 * c + d);
  return cd > 0.0 ? 2.0 * c + d : -d;
}
// The Burning Ship: the Mandelbrot set's step with both parts of z made
// positive first, followed the same way as mandelbrot() from its own
// orbit. Made positive, the imaginary part is 2|xy| + c.y, so its
// difference from the orbit's goes through diffabs. c's imaginary part is
// flipped, which stands the ship upright.
bool burningShip(vec2 dc, float pixel, out float escaped, out float r2, out vec2 dzp) {
  int row = int(q21);
  int limit = int(q9);
  dc.y = -dc.y;
  vec2 d = vec2(0.0);
  int m = 0;
  dzp = vec2(0.0);
  for (int i = 0; i < 1200; i++) {
    if (i >= limit) break;
    vec4 ref = orbitAt(row, m);
    if (ref.z < 0.5) {
      d += ref.xy;
      m = 0;
      ref = vec4(0.0);
    }
    vec2 z = ref.xy + d;
    // Not holomorphic, so this derivative is only near enough for the edge.
    dzp = 2.0 * cmul(abs(z), sign(z) * dzp) + vec2(pixel, 0.0);
    d = vec2(
      (2.0 * ref.x + d.x) * d.x - (2.0 * ref.y + d.y) * d.y,
      2.0 * diffabs(ref.x * ref.y, ref.x * d.y + ref.y * d.x + d.x * d.y)
    ) + dc;
    m++;
    z = orbitAt(row, m).xy + d;
    r2 = dot(z, z);
    if (r2 > 65536.0) {
      escaped = float(i);
      return true;
    }
    if (r2 < dot(d, d)) {
      d = z;
      m = 0;
    }
  }
  return false;
}
// The colour at one point on screen: q1/q2 the centre (for the Mandelbrot
// set and the Burning Ship its offset from the target q23/q24), q3 the height of the screen in
// the fractal's plane, q4 its turn, q5 the kind (0 the Mandelbrot set or
// a relative, 1 a Julia set of c = q6/q7, 3 the Burning Ship).
// How far the last fractalAt was from the set's edge, in pixels: far
// out, the picture is a smooth gradient.
float edgeDistance = 0.0;
vec3 fractalAt(vec2 s) {
  vec2 p = vec2(q1, q2) + turn2(s, q4) * q3;
  float pixel = q3 / texsize.y;
  vec3 col = vec3(0.004) + accent() * 0.02;
  float escaped = -1.0;
  float r2 = 0.0;
  float dist = 0.0;
  if (q5 < 0.5) {
    bool plain = q25 < 2.5 && q22 < 0.5;
    if (plain && q3 > 1e-4 && surelyInside(vec2(q23, q24) + p)) return col;
    vec2 dzp;
    if (!mandelbrot(p, pixel, escaped, r2, dzp)) return col;
    dist = 0.5 * sqrt(r2) * log(r2) / max(length(dzp), 1e-30);
  } else if (q5 > 2.5) {
    vec2 dzp;
    if (!burningShip(p, pixel, escaped, r2, dzp)) return col;
    dist = 0.5 * sqrt(r2) * log(r2) / max(length(dzp), 1e-30);
  } else {
    vec2 z = p;
    vec2 dz = vec2(1.0, 0.0);
    int limit = int(q9);
    for (int i = 0; i < 420; i++) {
      if (i >= limit) break;
      dz = 2.0 * cmul(z, dz);
      z = cmul(z, z) + vec2(q6, q7);
      r2 = dot(z, z);
      if (r2 > 65536.0) {
        escaped = float(i);
        break;
      }
    }
    if (escaped < 0.0) return col;
    dist = 0.5 * sqrt(r2) * log(r2) / max(length(dz), 1e-30) / pixel;
  }
  // Smooth iteration count, so the bands have no steps - counting the
  // iterations a Julia scene skipped by being redrawn further out (q20),
  // or each of those jumps would show.
  float mu = escaped + 1.0 - log2(0.5 * log2(r2)) / log2(q25) + q20;
  float t = mu * 0.025 + q8;
  vec3 a = accent();
  vec3 band = mix(a, coverTone(), 0.5 + 0.5 * cos(6.2832 * t));
  float ridge = 0.5 + 0.5 * cos(6.2832 * t * 3.0);
  col = band * (0.12 + 0.6 * ridge * ridge);
  // Far from the set, few iterations: kept dark, so the set stands out.
  col *= smoothstep(0.0, 10.0, mu);
  edgeDistance = dist;
  // The edge, dist pixels away, lights up thinly.
  float edge = exp(-dist * 2.0) * 0.7;
  col += mix(a, vec3(1.0), 0.5) * edge * (0.3 + 0.3 * min(q11, 1.5));
  return col;
}
 shader_body {
  vec2 s = (uv_orig - 0.5) / aspect.yx;
  s.y = -s.y;
  // This frame's sample sits somewhere else inside the pixel each time,
  // and last frame's picture at the same spot of the fractal is blended
  // in: an average over many frames, which keeps the filaments from
  // flickering. Only near the edge: last frame is kept in 8 bits, and in
  // a smooth gradient the blend gets stuck a step short, which the zoom
  // then drags across the picture as straight edges.
  vec3 now = fractalAt(s + vec2(q18, q19) / texsize.y);
  vec2 before = turn2(s, q14) * q13 + vec2(q15, q16);
  vec2 beforeUv = vec2(before.x, -before.y) * aspect.yx + 0.5;
  float known = step(0.0, beforeUv.x) * step(beforeUv.x, 1.0) * step(0.0, beforeUv.y) * step(beforeUv.y, 1.0);
  float fine = 1.0 - smoothstep(2.0, 6.0, edgeDistance);
  ret = mix(now, history(beforeUv), q17 * known * fine);
 }

preset.comp:
shader_body {
 vec3 col = texture(sampler_main, uv).rgb;
 vec3 glow = vec3(0.0);
 float spin = 6.2832 * fract(52.9829 * fract(dot(uv * texsize.xy, vec2(0.06711, 0.00584))));
 for (int i = 0; i < 16; i++) {
   float a = float(i) * 2.39996 + spin;
   float r = 0.007 * sqrt((float(i) + 0.5) / 16.0);
   vec2 o = vec2(cos(a), sin(a)) * r * vec2(aspect.y, 1.0);
   glow += max(texture(sampler_main, uv + o).rgb - 0.5, 0.0);
 }
 col += glow / 16.0 * 1.4;
 // A beat flashes what is bright: the edge of the set.
 col += max(col - 0.35, 0.0) * q10 * 1.6;
 col = 1.0 - exp(-col * 1.5);
 col *= 1.0 - 0.45 * pow(clamp(rad * 1.25, 0.0, 1.0), 2.5);
 // Between two fractals the picture dims and comes back.
 ret = col * q12;
}
